sys_script_client.script:
function onSubmit() {
    // Get field values
    var priority = g_form.getValue('priority');
    var shortDesc = g_form.getValue('short_description');

    // Check if Priority = 1 and Short Description is empty
    if (priority == '1' && shortDesc.trim() === '') {
        g_form.addErrorMessage("⚠️ Short Description is required for Priority 1 incidents.");
        return false; // stop form submission
    }

    return true; // allow form submission
}
